function getAllSeries() { return SERIES; }
function getSeriesById(id) { return SERIES.find(s => s.id === id) || null; }
function findTest(seriesId, sectionIdx, testIdx) {
  const s = getSeriesById(seriesId);
  if (!s) return null;
  const sec = s.sections[sectionIdx];
  if (!sec) return null;
  const t = sec.tests[testIdx];
  if (!t) return null;
  return { series: s, section: sec, test: t };
}
